<?php require __DIR__.'/../config/db.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $b=body();$st=$pdo->prepare('SELECT id FROM absensi WHERE siswa_id=? AND tanggal=CURDATE()');$st->execute([$b['siswa_id']??0]);if($st->fetch()){http_response_code(409);out(['error'=>'Siswa sudah absen hari ini']);}$st=$pdo->prepare("INSERT INTO absensi(siswa_id,tanggal,jam,status) VALUES(?,CURDATE(),CURTIME(),?)");$st->execute([$b['siswa_id'],$b['status']??'Hadir']);out(['ok'=>true]); } $date=$_GET['date']??date('Y-m-d');$st=$pdo->prepare("SELECT a.id,s.nama,k.nama kelas,TIME_FORMAT(a.jam,'%H:%i:%s') jam,a.status FROM absensi a JOIN siswa s ON s.id=a.siswa_id JOIN kelas k ON k.id=s.kelas_id WHERE a.tanggal=? ORDER BY a.jam");$st->execute([$date]);$rows=$st->fetchAll();$counts=['Hadir'=>0,'Sakit'=>0,'Izin'=>0,'Alpa'=>0];foreach($rows as $r)$counts[$r['status']]++;out(['rows'=>$rows,'counts'=>['hadir'=>$counts['Hadir'],'sakit'=>$counts['Sakit'],'izin'=>$counts['Izin'],'alpa'=>$counts['Alpa']]]);
